3: struct EmbeddedBinary: Identifiable {
4:     let id = UUID()
5:     let path: String
6:     let data: Data
7: }
8: 
9: enum ArchiveFailure: LocalizedError {
10:     case unsupported(String)
11:     var errorDescription: String? {
12:         if case let .unsupported(message) = self { return message }
13:         return "无法解包"
14:     }
15: }
