3: struct BinaryReader {
4:     let data: Data
5:     func u8(_ offset: Int) -> UInt8? { guard offset >= 0 && offset < data.count else { return nil }; return data[offset] }
6:     func u16(_ offset: Int, big: Bool = false) -> UInt16? {
7:         guard offset >= 0, offset + 2 <= data.count else { return nil }
8:         let v = UInt16(data[offset]) | UInt16(data[offset + 1]) << 8
9:         return big ? v.byteSwapped : v
10:     }
11:     func u32(_ offset: Int, big: Bool = false) -> UInt32? {
12:         guard offset >= 0, offset + 4 <= data.count else { return nil }
13:         let v = UInt32(data[offset]) | UInt32(data[offset+1]) << 8 | UInt32(data[offset+2]) << 16 | UInt32(data[offset+3]) << 24
14:         return big ? v.byteSwapped : v
15:     }
16:     func u64(_ offset: Int, big: Bool = false) -> UInt64? {
17:         guard let lo = u32(offset), let hi = u32(offset + 4) else { return nil }
18:         let v = UInt64(lo) | UInt64(hi) << 32
19:         return big ? v.byteSwapped : v
20:     }
21:     func text(_ offset: Int, _ length: Int) -> String {
22:         guard offset >= 0, length >= 0, offset <= data.count, length <= data.count - offset else { return "" }
23:         return String(decoding: data[offset..<offset+length], as: UTF8.self).trimmingCharacters(in: .controlCharacters.union(.whitespaces))
24:     }
25:     func cString(_ offset: Int, max: Int = 512) -> String {
26:         guard offset >= 0, offset < data.count else { return "" }
27:         let end = min(data.count, offset + max)
28:         let slice = data[offset..<end].prefix(while: { $0 != 0 })
29:         return String(decoding: slice, as: UTF8.self)
30:     }
31: }
